import {graphPredictionHtml} from './player-graph-prediction-ui.mjs?v=2026-10-31.2';
import {gbdtHtml} from './gbdt-ui.mjs';
export function trainingHtml(bundle,result,{esc,number,pct,date}){
 const t=result.training,p=result.prediction,actual=bundle.actual;
 const actualHtml=bundle.target?.finished&&Number.isFinite(actual?.homeScore)&&Number.isFinite(actual?.awayScore)?`<div class="callout"><b>Gerçek sonuç: ${esc(bundle.target.home.name)} ${actual.homeScore} – ${actual.awayScore} ${esc(bundle.target.away.name)}</b><br>Bu tamamlanmış maç için başlama öncesindeki verilerle geriye dönük tahmin gösterilir. Gerçek sonucun model olasılığı: ${pct(p?.heatmap?.find(c=>c.home===actual.homeScore&&c.away===actual.awayScore)?.probability,2)}. En olası skor, gerçekleşen sonuçtan farklı olabilir.</div>`:'';
 if(!t?.report)return `<section class="card spaced training-report" id="training-report"><h2>Geçmiş sonuçlarla öğrenme</h2><p class="inline-note">${esc(t?.reason??'Bu maç için uygun eğitim verisi bulunmuyor; takım ağı tabanı kullanılıyor.')}</p>${gbdtHtml(t,{esc,number,pct})}${actualHtml}</section>`;
 const b=t.report.test.baseline,s=t.report.test.selected;
 const metrics=[['Skor log kaybı (düşük daha iyi)',number(b.pairedCountNll,3),number(s.pairedCountNll,3)],['1X2 log kaybı (düşük daha iyi)',number(b.logLoss,3),number(s.logLoss,3)],['Brier (düşük daha iyi)',number(b.brier,3),number(s.brier,3)],['1X2 isabeti',pct(b.accuracy),pct(s.accuracy)],['Tam skor isabeti',pct(b.exactScoreAccuracy),pct(s.exactScoreAccuracy)],['Gol ortalama mutlak hatası',number(b.goalMAE,3),number(s.goalMAE,3)]];
 return `<section class="card spaced training-report" id="training-report"><div class="card-title"><h2>Geçmiş sonuçlarla öğrenme</h2><span class="tag">${t.accepted?'EĞİTİLMİŞ MODEL':'TABAN MODEL KORUNDU'}</span></div><p class="small-text">${number(t.counts.eligible,0)} geçmiş maç · ${t.scope.type==='league'?'Bu ligden':'Lig örneklemi az; tüm liglerden'} · ${date(t.ranges.eligible.firstDate,true)} – ${date(t.ranges.eligible.lastDate,true)}. Hedef maç ve analiz anında bitmemiş maçlar eğitimden çıkarılır. Aynı öğrenilmiş gol tabanı ve dağılımı skor projeksiyonunda ve simülasyonda kullanılır.</p><div class="mini-stats"><div><b>${t.counts.train}</b><span>EĞİTİM</span></div><div><b>${t.counts.validation}</b><span>AYAR DOĞRULAMASI</span></div><div><b>${t.counts.test}</b><span>AYRI TUTULAN TEST</span></div></div><p class="inline-note">${esc(t.reason)} Dağılım: ${t.shape?'Negatif binom (k='+number(t.shape,0)+')':'Poisson'}. ${t.accepted?'Benzer maçların etkisi ağ/form özellikleri üzerinden öğrenilir; sabit skor karışımı eklenmez.':''}</p>${gbdtHtml(t,{esc,number,pct})}${graphPredictionHtml(t,{esc,number,pct})}${actualHtml}<details><summary>Eğitimden ayrı tutulan maçlarda sonuçlar</summary><p class="inline-note">${date(t.ranges.test.firstDate,true)} – ${date(t.ranges.test.lastDate,true)} · ${t.counts.test} test maçı. Ağaç / katsayı ve dağılım seçimi bu test sonuçlarını görmeden yapılır.</p><div class="table-wrap"><table><thead><tr><th>ÖLÇÜM</th><th>HAM POISSON TABANI</th><th>ÖĞRENİLEN MODEL</th></tr></thead><tbody>${metrics.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="inline-note">Bu, aynı kaynaktaki zaman sıralı iç testtir; gelecekte aynı başarıyı garanti etmez. Bu ölçümler oyuncu/H2H senaryolarını ve değişiklik politikasını doğrulamaz. ${t.training.finalRefitCount>0?'Test tamamlandıktan sonra yayınlanan model, hedef maçtan önceki '+t.training.finalRefitCount+' uygun maçla tekrar eğitilir;':'Doğrulama seçimine göre taban katsayılar korunur;'} tablodaki ölçüm bu son tekrar eğitiminden önce dondurulan modele aittir.</p></details><details><summary>Öğrenilen model ve kapsam kaydı</summary><pre class="training-json">${esc(JSON.stringify(t,null,2))}</pre></details></section>`;
}
